<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Cat FAQ</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #080b12;
      --panel: rgba(17, 24, 39, 0.82);
      --panel-strong: rgba(24, 33, 51, 0.95);
      --text: #eef4ff;
      --muted: #aab6ca;
      --accent: #8bd3ff;
      --accent-strong: #c084fc;
      --border: rgba(255, 255, 255, 0.12);
      --shadow: rgba(0, 0, 0, 0.36);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at 18% 8%, rgba(139, 211, 255, 0.2), transparent 32rem),
        radial-gradient(circle at 82% 18%, rgba(192, 132, 252, 0.2), transparent 30rem),
        linear-gradient(145deg, #05070d 0%, var(--bg) 48%, #111827 100%);
    }

    main {
      width: min(920px, calc(100% - 32px));
      margin: 0 auto;
      padding: 72px 0;
    }

    .hero {
      margin-bottom: 34px;
      text-align: center;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin: 0 0 14px;
      padding: 8px 14px;
      border: 1px solid var(--border);
      border-radius: 999px;
      color: var(--accent);
      background: rgba(139, 211, 255, 0.08);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.45rem, 7vw, 5rem);
      line-height: 0.95;
      letter-spacing: -0.06em;
    }

    .subtitle {
      max-width: 670px;
      margin: 20px auto 0;
      color: var(--muted);
      font-size: clamp(1rem, 2vw, 1.2rem);
      line-height: 1.7;
    }

    .details {
      display: grid;
      gap: 16px;
      padding: 18px;
      border: 1px solid var(--border);
      border-radius: 28px;
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03));
      box-shadow: 0 28px 80px var(--shadow);
      backdrop-filter: blur(18px);
    }

    .example {
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 20px;
      background: var(--panel);
      transition: border-color 180ms ease, background 180ms ease, transform 180ms ease;
    }

    .example:has(.question[aria-expanded="true"]) {
      border-color: rgba(139, 211, 255, 0.42);
      background: var(--panel-strong);
      transform: translateY(-1px);
    }

    .question {
      display: flex;
      width: 100%;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
      padding: 22px 24px;
      border: 0;
      color: inherit;
      background: transparent;
      cursor: pointer;
      font: inherit;
      text-align: left;
    }

    .question:focus-visible {
      outline: 3px solid rgba(139, 211, 255, 0.55);
      outline-offset: -6px;
    }

    .question-title {
      font-size: 1.05rem;
      font-weight: 760;
      letter-spacing: -0.015em;
    }

    .icon {
      display: grid;
      width: 34px;
      height: 34px;
      flex: 0 0 auto;
      place-items: center;
      border-radius: 50%;
      color: var(--accent);
      background: rgba(139, 211, 255, 0.1);
      font-size: 1.35rem;
      transition: transform 180ms ease, background 180ms ease;
    }

    .question[aria-expanded="true"] .icon {
      background: rgba(192, 132, 252, 0.18);
      color: var(--accent-strong);
      transform: rotate(45deg);
    }

    .answer {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 220ms ease;
    }

    .answer[aria-hidden="false"] {
      grid-template-rows: 1fr;
    }

    .answer-inner {
      overflow: hidden;
    }

    .answer p {
      margin: 0;
      padding: 0 24px 24px;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.7;
    }

    footer {
      margin-top: 24px;
      color: rgba(238, 244, 255, 0.56);
      font-size: 0.92rem;
      text-align: center;
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const faqs = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel relaxed, but purring can also be self-soothing. Some cats purr when they are stressed, recovering, or asking for attention."
      },
      {
        question: "How much sleep do cats need?",
        answer: "Most adult cats sleep 12 to 16 hours a day. Kittens and senior cats may sleep even longer because growth and recovery take extra energy."
      },
      {
        question: "Should cats live indoors or outdoors?",
        answer: "Indoor cats are generally safer from cars, predators, disease, and extreme weather. Enrichment like climbing spaces, toys, windows, and play sessions helps indoor cats thrive."
      },
      {
        question: "Why do cats knead blankets or people?",
        answer: "Kneading is a comforting behavior that begins in kittenhood. Adult cats often knead soft surfaces when they feel secure, affectionate, or ready to nap."
      },
      {
        question: "How can I tell if a cat is happy?",
        answer: "Look for relaxed posture, slow blinking, soft tail movement, playfulness, grooming, and choosing to be near you. Every cat is different, so consistent changes in behavior matter most."
      }
    ];

    function Header() {
      return `
        <section class="hero" aria-labelledby="page-title">
          <p class="eyebrow">Cat care basics</p>
          <h1 id="page-title">Frequently Asked Questions About Cats</h1>
          <p class="subtitle">
            Clear answers for curious humans, from mysterious purrs to healthy indoor routines.
          </p>
        </section>
      `;
    }

    function FAQItem(item, index) {
      const answerId = `answer-${index}`;

      return `
        <div class="example">
          <button class="question" type="button" aria-expanded="false" aria-controls="${answerId}">
            <span class="question-title">${item.question}</span>
            <span class="icon" aria-hidden="true">+</span>
          </button>
          <div class="answer" id="${answerId}" aria-hidden="true">
            <div class="answer-inner">
              <p>${item.answer}</p>
            </div>
          </div>
        </div>
      `;
    }

    function FAQList(items) {
      return `
        <section class="details" aria-label="Cat FAQ">
          ${items.map(FAQItem).join("")}
        </section>
      `;
    }

    function App() {
      return `
        ${Header()}
        ${FAQList(faqs)}
        <footer>Questions are collapsed by default. Select any question to expand its answer.</footer>
      `;
    }

    document.querySelector("#app").innerHTML = App();

    document.querySelectorAll(".example").forEach((example) => {
      const button = example.querySelector(".question");
      const answer = example.querySelector(".answer");

      button.addEventListener("click", () => {
        const isExpanded = button.getAttribute("aria-expanded") === "true";
        button.setAttribute("aria-expanded", String(!isExpanded));
        answer.setAttribute("aria-hidden", String(isExpanded));
      });
    });
  </script>
</body>
</html>
